import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`linkedin-resume`,heroTitle:`Turn your LinkedIn into a resume in minutes`,heroSubtitle:`Perplexity Computer extracts your profile, writes quantified achievement bullets, and delivers an ATS-optimized resume — automatically.`,inputUrlCta:`Build my resume`,inputUrlPlaceholder:`www.linkedin.com/in/yourprofile`,inputUrlPrefill:`Go to {url} and extract the full professional profile — work history, education, skills, certifications, and accomplishments. Then build a polished, ATS-optimized resume with: (1) A strong professional summary, (2) Quantified achievement bullets for each role, (3) Skills section optimized for ATS keyword matching, (4) Clean formatting that passes ATS parsers. Deliver the resume in both PDF and Word formats.`,heroOverlaySteps:[`Extracting your work history, skills, and accomplishments`,`Researching job market keywords for your target roles`,`Writing quantified achievement bullets and ATS-optimized summary`,`Polished resume in PDF and Word ready`],generatingSteps:[`Visiting {url} to extract your full professional profile`,`Designing agent to optimize for ATS keyword matching`,`Configuring achievement quantification and summary writing`,`Setting up resume in PDF and Word formats`],featureSectionTitle:`From LinkedIn to polished resume`,featureCardTitles:[`Connects to your career tools`,`Resume ready to submit`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`LinkedIn, Google Docs, Notion, Indeed — Computer plugs into your tools so profile data, resume drafts, and applications flow in one workflow.`,`ATS-optimized formatting. Quantified achievements. Professional summary. Computer delivers a polished resume you can submit to any job board immediately.`],capabilitySectionTitle:`Your resume writer, on demand`,capabilitySectionSubtitle:`Paste your LinkedIn URL, get back an ATS-optimized resume.`,capabilityCards:[{title:`Profile Extraction`,description:`Computer can pull your full professional history from LinkedIn — work experience, education, skills, certifications, and accomplishments — and structure it for a resume.`},{title:`ATS Optimization`,description:`Computer can research recruiter search patterns and ATS keyword requirements for your target roles — ensuring your resume passes automated screening.`},{title:`Achievement Quantification`,description:`Computer can transform vague job descriptions into quantified achievement bullets with metrics, impact statements, and action verbs that recruiters look for.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Notion, Indeed, and more — build workflows that keep your resume, cover letters, and applications in one place.`},{title:`Remember & Learn`,description:`Computer can remember your career history, target roles, and past resume versions across sessions — so every update builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch job postings for your target roles and alert you when new opportunities match your profile — so you never miss a fit.`}]});export{t as default};
